mapper.select:
SELECT t.topic_id AS id, c.category_name AS category, t.title, t.difficulty, t.duration_min, t.duration_max, t.guide_text AS guide, IF(f.topic_id IS NULL, 0, 1) AS favorite FROM topics t INNER JOIN categories c ON c.category_id = t.category_id LEFT JOIN user_favorites f ON f.topic_id = t.topic_id AND f.user_id = #{userId}
AND c.category_name = #{category}
AND t.title LIKE CONCAT('%', #{keyword}, '%')
ORDER BY t.sort_order

SELECT COUNT(*)
FROM user_favorites
WHERE user_id = #{userId}
  AND topic_id = #{topicId}

mapper.delete:
DELETE FROM user_favorites
WHERE user_id = #{userId}
  AND topic_id = #{topicId}
